    big = order(shop, "c2", ("LAMP", 2)).body["order_id"]  # 12_000 -> 10_200
    small = order(shop, "c2", ("PEN", 3)).body["order_id"]  # 900, no discount

    orders = shop.insights.handle_order_history("c2").body["orders"]
    totals = {o["order_id"]: o["total_cents"] for o in orders}
    assert totals[big] == 10_200
    assert totals[small] == 900
    assert totals[big] == shop.orders.handle_get(big).body["total_cents"]
    assert totals[small] == shop.orders.handle_get(small).body["total_cents"]


def test_lifetime_value_is_unknown_customer_404(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_lifetime_value_with_no_orders_is_zero(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_orders_and_includes_discounts(shop):
    order(shop, "c2", ("LAMP", 2))  # 12_000 -> 10_200 after 15% gold discount
    order(shop, "c2", ("PEN", 3))  # 900, no discount
    cancelled = order(shop, "c2", ("BOOK", 4)).body["order_id"]  # excluded
    shop.orders.handle_cancel(cancelled)

    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": 11_100}


def test_top_customers_rejects_bad_limit(shop):
    for bad in (0, -1, True, False, "3", 2.0, None):
        response = shop.insights.handle_top_customers(bad)
        assert response.status == 400
        assert "error" in response.body


